"""Original question-led copy and enquiry presentation for the final revision."""
from pathlib import Path
import html,json

ROOT=Path(__file__).resolve().parent
E=lambda x:html.escape(str(x),quote=True)
PRIORITIES=['Still exploring','Reach the right customers','Strengthen our brand or website','Improve a process or build software','Connect data, CRM or automation']
SERVICE_CONTEXT={
 'strategy':('What deserves your next investment?','Tell us the decision you are weighing up, what you want to achieve and what you have tried.','Still exploring'),
 'performance-marketing':('What would a better enquiry look like?','Tell us what you sell, who you want to reach and what happens after someone enquires.','Reach the right customers'),
 'seo-content-social':('What do your customers need to understand?','Tell us who you want to reach, what you want to be known for and where people currently find you.','Reach the right customers'),
 'brand-creative-ai':('How should people see your business?','Tell us what is changing: your audience, positioning, offer, identity or the way you present your work.','Strengthen our brand or website'),
 'websites':('What should your next website make possible?','Share your current website, who it needs to serve and the action you want visitors to take.','Strengthen our brand or website'),
 'data-crm-automation':('Where does your team lose track of the next step?','Describe one handover, report or recurring task that needs to work better.','Connect data, CRM or automation'),
 'custom-software-ai':('Which part of the work needs a better system?','Describe the process, who uses it and what becomes difficult as the work grows.','Improve a process or build software'),
}

def industry_answers():
    p=ROOT/'industry_answers.json'
    return json.loads(p.read_text()) if p.exists() else {}

def lead_section(path='',title='',standalone=False):
    context=title or 'Digiator homepage'
    invitation='What would you like to be different?'
    prompt='A website for a new market. Better enquiries. Software for a recurring process. Tell us what you have in mind.'
    priority=PRIORITIES[0]
    if path.startswith('services/'):
        invitation,prompt,priority=SERVICE_CONTEXT.get(path.split('/')[-1],(invitation,prompt,priority))
    elif path.startswith('industries/'):
        data=industry_answers().get(path.split('/')[-1],{})
        invitation=data.get('invitation',invitation);prompt=data.get('prompt',prompt)
    elif path.startswith('case-studies/'):
        invitation='Have a situation this work reminds you of?'
        prompt='Tell us what is similar in your business, what is different and what you would like to change.'
    elif path=='resources':
        invitation='Found a question worth working on?'
        prompt='Tell us what you noticed while using a workbook and which part you would like help with.'
    if standalone:invitation='Start with what you want to achieve.'
    options=''.join(f'<option {"selected" if x==priority else ""}>{E(x)}</option>' for x in PRIORITIES)
    return f'''<section class="section lead-section" id="start"><div class="wrap lead-layout"><div class="lead-invitation"><div class="eyebrow">Your first conversation</div><h2>{E(invitation)}</h2><p>You can bring a finished brief, a new opportunity, or something you haven’t quite figured out yet.</p><ol class="call-expectations"><li><span>01</span><div><strong>Tell us the situation.</strong><p>What you want to achieve and what’s already in place.</p></div></li><li><span>02</span><div><strong>Talk with a co-founder.</strong><p>We’ll explore the priority, the fit and what needs a closer look.</p></div></li><li><span>03</span><div><strong>Agree the next step.</strong><p>Where there’s a fit, we move toward a meeting and a scoped proposal.</p></div></li></ol><div class="consultation-facts"><b>Free initial consultation</b><span>20–30 minutes · With a co-founder</span></div><p class="response-note">We usually respond within one hour. Enquiries are welcome 24/7.</p><a class="line-link" href="https://wa.me/919343117867" target="_blank" rel="noopener noreferrer">Prefer to message us directly? <span aria-hidden="true">↗</span></a></div><form class="contact-form final-enquiry" id="consultation-form"><span class="form-kicker">A few details are enough to begin.</span><h3>Tell us what you’re planning.</h3><p class="form-intro">Fill this in, then send your message through WhatsApp or your email app.</p><input type="hidden" name="page" value="{E(context)}"><div class="field-row"><div class="field"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" required maxlength="100"></div><div class="field"><label for="company">Business or organisation</label><input id="company" name="company" autocomplete="organization" required maxlength="160"></div></div><div class="field"><label for="contact">Email or WhatsApp number</label><input id="contact" name="contact" required maxlength="180" type="text" autocomplete="email" aria-describedby="contact-hint"><p class="form-help" id="contact-hint">Whichever is easiest for us to reach you on.</p></div><div class="field"><label for="need">Where would you like to start? <span class="optional">Optional</span></label><select id="need" name="need">{options}</select></div><div class="field"><label for="message">What would you like to improve or build?</label><textarea id="message" name="message" required minlength="10" maxlength="2500" placeholder="{E(prompt)}"></textarea><p class="form-help">A few sentences are enough. Please leave out personal or confidential records.</p></div><label class="form-consent"><input type="checkbox" name="consent" required><span>I’d like Digiator to respond to this enquiry. I have read the <a href="/privacy/">privacy information</a>.</span></label><div class="actions"><button type="submit" class="btn dark">Continue on WhatsApp <span class="arrow" aria-hidden="true">↗</span></button><button id="email-enquiry" type="button" class="btn light-outline">Use email instead</button></div><p class="send-explainer">You’ll review and send the message in the app you choose. Sending an enquiry doesn’t commit you to a project.</p><p id="enquiry-status" class="form-status" role="status"></p><noscript><p>Email <a href="mailto:growth@digiator.com">growth@digiator.com</a> or message <a href="https://wa.me/919343117867">+91 93431 17867</a> to start.</p></noscript></form></div></section>'''

def render_home(g):
    link,flow,visual,workcard,page,faq_html=(g[n] for n in ['link','flow','visual','workcard','page','faq_html'])
    hero=f'''<section class="hero"><div class="wrap"><div class="hero-grid"><div><div class="eyebrow">Digiator · Your Digital Launchpad</div><h1>Grow your business.<br><em>Build what it needs.</em></h1><p class="lead">Reach the right customers. Make your value easier to see. Give your team better tools.</p><p class="hero-explanation">We bring strategy, marketing, design and software together around the next move you want to make.</p><div class="actions">{link('#start','Request a Free Consultation','btn')}{link('/case-studies/','See the work behind it')}</div><p class="hero-micro">20–30 minutes with a co-founder. A finished brief can wait.</p></div>{visual()}</div><div class="hero-bottom"><span><i class="dot"></i>Live manufacturing software</span><span>Five-city healthcare campaign</span><span>Selected client relationships <strong>2+ years</strong></span></div></div></section>'''
    journeys=[
      ('growth','Reach better customers','More enquiries are only the beginning.','People need a reason to enquire—and your team needs a way to turn that interest into a useful conversation. We connect the audience, offer, landing page and follow-up.',['An offer that speaks to the right buyer','A page that answers the questions before the enquiry','Reporting that follows what happens next'],'performance-marketing','healthcare','Reach the right customers'),
      ('presence','Look as good as your work','Your business has moved on. Has the way you present it?','A new market, a stronger offer or better work deserves a presence that makes its value clear. We shape the positioning, identity, content and website around the customers you want next.',['A reason to choose you that people can explain','A recognisable identity across the touchpoints that matter','A website that helps visitors decide and act'],'brand-creative-ai','brand','Strengthen our brand or website'),
      ('operations','Make work run better','Put the process in a system your team can use.','When work depends on repeated entries, remembered rules or approvals scattered across messages, the next step gets harder to trust. We map the process and build around the people who run it.',['Roles, rules and exceptions made explicit','A working core your team can test and review','Reporting, handover and support agreed in the scope'],'custom-software-ai','production','Improve a process or build software')]
    tabs=''.join(f'<button id="tab-{key}" role="tab" aria-selected="{"true" if i==0 else "false"}" aria-controls="panel-{key}" tabindex="{0 if i==0 else -1}" class="journey-tab" data-priority="{E(priority)}"><span>0{i+1}</span>{E(name)}</button>' for i,(key,name,*rest,priority) in enumerate(journeys))
    panels=''
    for i,(key,name,title,desc,points,slug,demo,priority) in enumerate(journeys):
        panels+=f'<div id="panel-{key}" role="tabpanel" aria-labelledby="tab-{key}" class="journey-panel" {"hidden" if i else ""}><div><h3>{E(title)}</h3><p>{E(desc)}</p><ul class="text-list">'+''.join(f'<li>{E(p)}</li>' for p in points)+f'</ul>{link("/services/"+slug+"/","See what this involves")}</div>{flow(demo)}</div>'
    recognition=f'<section class="section"><div class="wrap"><div class="intro-layout"><div class="eyebrow">What do you want to change?</div><div><h2>Start where<br><em>it matters to you.</em></h2><p>You may know exactly what you need. Or you may know what needs to be different. Either is a good place to start.</p></div></div><div class="journey-tabs" role="tablist" aria-label="Your business priority">{tabs}</div>{panels}</div></section>'
    proof=f'<section class="section work-section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">What has this looked like in practice?</div><h2>The work.<br><em>And what happened next.</em></h2></div><p>A campaign and a production system answer different business questions. Here’s how the work took shape.</p></div><div class="work-grid">{workcard(g["CASES"][1])}{workcard(g["CASES"][0])}</div><div class="proof-tail"><span>Different engagements. Stated results. The context behind each figure.</span>{link('/case-studies/','Explore all six case studies')}</div></div></section>'
    rows=''.join(f'<a class="service-row" href="/services/{s["slug"]}/"><span class="number">0{i+1}</span><div><h3>{E(s["name"])}</h3><p>{E(s["short"])}</p></div><span class="arrow" aria-hidden="true">↗</span></a>' for i,s in enumerate(g['SERVICES']))
    capabilities=f'<section class="section"><div class="wrap capabilities"><div><div class="eyebrow">What could we put to work for you?</div><h2>The skills follow<br><em>the job.</em></h2><p>A website can be the whole project. So can a campaign, a new identity or an internal system. When the work crosses disciplines, we bring those skills together.</p><p><strong>You don’t have to buy everything to get the part you need.</strong></p></div><div>{rows}</div></div></section>'
    selected=['healthcare-and-medical','manufacturing-and-industrial','real-estate-and-property','education-and-training','architecture-interiors-and-home-improvement','technology-saas-and-startups']
    sector_cards=''
    for slug in selected:
        sector=next(x for x in g['INDUSTRIES'] if x['slug']==slug)
        sector_cards+=f'<a class="sector-link" href="/industries/{slug}/"><span>{E(sector["name"])}</span><small>See the work this can involve <span class="arrow" aria-hidden="true">↗</span></small></a>'
    sectors=f'<section class="section sector-section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Will this fit the way our business works?</div><h2>Your industry changes<br><em>the answer.</em></h2></div><p>A patient needs confidence before booking. A property buyer needs a reason to visit. A production team needs a calculation it can trace. We start with those decisions.</p></div><div class="sector-grid">{sector_cards}</div>{link('/industries/','Find your industry · all 20 sectors')}</div></section>'
    method=g['method_html']([
      ('Bring the situation.','We discuss the objective, what already exists and who is involved. The first call helps establish fit and the next information needed.','01 / FIRST CONVERSATION'),
      ('See the shape of the work.','We define deliverables, responsibilities, cost and timing in a proposal. If deeper research or technical discovery is needed, we scope it first.','02 / SCOPE & DECISIONS'),
      ('Build it with us.','You review the work as it takes shape. Testing, launch, access, handover and ongoing support follow the agreed scope.','03 / BUILD & DELIVERY')])
    process=f'<section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">How does a conversation become a project?</div><h2>Know what you’re<br><em>saying yes to.</em></h2></div><p>You should be able to see the work, understand the decisions and know who needs to act next.</p></div>{method}</div></section>'
    questions=[('Do I need to know which service to ask for?','No. Tell us what you want to achieve or what has become difficult. If you already have a brief, bring it—we can start there.'),('Can you work with our existing team and tools?','Yes, where the project allows. We first understand what is working, the access available and who will own each responsibility. A new platform is not assumed.'),('How do you decide the cost and timeline?','We look at the deliverables, complexity, dependencies and review process. Those become a scoped proposal. The initial consultation is free; deeper audits or technical discovery are agreed separately.'),('What will we own when the work is complete?','Your agreement sets out the custom deliverables, code, assets, data and access to be handed over, subject to its terms and payment. Third-party licences, hosting and ongoing services are identified separately.')]
    objections=f'<section class="section decision-questions"><div class="wrap decision-layout"><div><div class="eyebrow">Before you get in touch</div><h2>A few things<br><em>worth knowing.</em></h2><p>There’s room for a specific project, a wider plan, or an objective that still needs defining.</p>{link('/resources/','Want to think it through first? Try a workbook')}</div>{faq_html(questions)}</div></section>'
    page('','Growth, websites & software built around your business','Grow your business and improve how it runs. Digiator combines strategy, marketing, brand, websites and software. Request a free co-founder consultation.',hero+recognition+proof+capabilities+sectors+process+objections+lead_section(),include_cta=False)

def render_consultation(g,path='consultation'):
    if path=='consultation':
        title='You don’t need a perfect brief. Just a place to start.'
        intro='Tell us what you want to change, build or understand. Your first conversation is with a co-founder, so we can explore the business behind the brief.'
    else:
        title='Let’s get the right conversation started.'
        intro='A new project, an idea to explore or a question about existing work—here’s how to reach the team.'
    content=g['pagehero']('Talk to Digiator',title,intro,[('Consultation' if path=='consultation' else 'Contact','')],False)
    if path=='contact':
        content+='''<section class="contact-routes"><div class="wrap"><div><small>New projects</small><a href="mailto:growth@digiator.com">growth@digiator.com</a></div><div><small>Phone & WhatsApp</small><a href="https://wa.me/919343117867">+91 93431 17867</a></div><div><small>Existing clients</small><a href="mailto:operations@digiator.com">operations@digiator.com</a></div></div></section>'''
    content+=lead_section(path,'Consultation' if path=='consultation' else 'Contact',standalone=True)
    g['page'](path,'Free consultation' if path=='consultation' else 'Contact Digiator',intro,content,include_cta=False)

def render_about(g):
    content=g['pagehero']('About Digiator','Good work starts by understanding what matters to you.','You bring the business context. We bring strategy, creative and technology—and the judgement to connect them around the work.',[('About','')],False)
    content=f'''{content}<section class="section"><div class="wrap about-layout"><div><div class="eyebrow">Your Digital Launchpad</div><h2>Some briefs arrive finished.<br><em>Others start as a conversation.</em></h2><p>“We need a website.” “We want better enquiries.” “This process is taking too much time.” Those are all useful places to begin.</p><p>Our job is to understand what that change needs to do for the business, then turn it into work you can see, review and use.</p><p>That can mean a focused campaign, a new brand or website, or software built around an operational process. The capabilities follow the brief.</p>{g['link']('/case-studies/','See how that thinking becomes work')}</div>{g['visual']()}</div></section>'''
    principles=[('Understand before prescribing.','We ask about the people, objective and existing work before recommending the scope.'),('Make decisions with something concrete.','Plans, designs, working stages and documented responsibilities help everyone see what is being agreed.'),('Explain what a result means.','Case studies separate the delivered work, reported outcomes and assumptions behind estimates.'),('Think beyond launch day.','Access, handover, ownership terms and support belong in the conversation before the project ends.')]
    content+='<section class="section work-section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">What working together should feel like</div><h2>Clear enough to trust.<br><em>Practical enough to use.</em></h2></div></div><div class="principles">'+''.join(f'<div class="principle"><h3>{a}</h3><p>{b}</p></div>' for a,b in principles)+'</div></div></section>'
    content+='''<section class="section"><div class="wrap page-layout"><div class="eyebrow">Leadership & accountability</div><div class="body-copy"><h2>Kanchan Sonvani<br><span class="muted" style="font-size:22px">Co-founder</span></h2><p>Your initial conversation is with a co-founder. We discuss what you are trying to achieve, whether Digiator is the right fit, and what needs to happen next.</p><p>Based in Indore, Madhya Pradesh, Digiator works across India and considers selected international engagements.</p></div></div></section>'''
    g['page']('about','About Digiator','Founder-led conversations, connected skills and work built around your business. Meet the approach behind Digiator.',content,'about')
